import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2022-10-19","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2022-10-19","date":"2022-10-19T00:00:00.000Z","updated":"2022-10-21T00:00:00.000Z","tags":["Ceph","RGW","Refactoring","Distributed Storage","Multi","part Uploads"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-10-19.md","filePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-10-19.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-10-19.md"};function i(n,t,s,g,h,d){return e(),r("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2022年10月19日</li><li><strong>参与人员</strong>: 包括新成员，鼓励大家积极提出议题。</li><li><strong>主要议题</strong>: 讨论了MQTT消息转换到S3对象的小型项目，以及多部分上传对象的问题和解决方案。</li></ul><h4 id="主要讨论内容" tabindex="-1">主要讨论内容 <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容&quot;">​</a></h4><ol><li><p><strong>MQTT消息转换项目介绍</strong></p><ul><li><strong>项目背景</strong>: Yuval介绍了一个针对工业物联网的项目，使用MQTT协议，部分信息需短期管理，部分需长期存储。</li><li><strong>项目目标</strong>: 提高将MQTT消息作为S3对象存储的效率，通过转换器将消息聚合为对象。</li><li><strong>技术细节</strong>: 包括MQTT代理、S3端点、聚合逻辑和桶与主题的映射，以及一个Python代码从聚合对象中提取原始消息。</li></ul></li><li><p><strong>多部分上传对象问题讨论</strong></p><ul><li><strong>问题描述</strong>: 讨论了因重复上传导致的多部分上传对象中的孤立数据问题，对计费的影响。</li><li><strong>解决方案</strong>: 探讨了使用多部分上传API进行结构化数据上传的可能性，以及改进上传流程以避免问题。</li><li><strong>合作与进展</strong>: 提到了与Matt的合作，以及代码审查和测试以推进解决方案。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>项目推进</strong>: Yuval的项目将继续进行，包括容器化和在Kubernetes环境中的部署。</li><li><strong>问题解决</strong>: 将与Matt合作，共同探讨和实现多部分上传对象的解决方案。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>技术实施</strong>: 完善MQTT消息转换项目，确保其在实际环境中的有效性和稳定性。</li><li><strong>问题解决</strong>: 与Matt合作，进行代码审查和测试，以确保解决方案的可行性。</li><li><strong>沟通与协作</strong>: 保持团队沟通，确保所有参与者对项目进展和问题解决有清晰的了解。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>会议记录</strong>: 鼓励所有参与者在有新议题时更新会议文档。</li><li><strong>技术支持</strong>: 提供了使用Jaeger进行多部分上传跟踪的建议，以帮助管理和调试相关问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li><strong>下次会议</strong>: 提醒所有参与者下次会议的时间，并鼓励提出新的议题和建议。</li></ul>',13)])])}const c=a(l,[["render",i]]);export{_ as __pageData,c as default};
